<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\SiteContent; use App\Models\Testimonial; use Illuminate\Http\Request;
class SiteContentController extends Controller {
 public function publicContent(){return response()->json(['data'=>SiteContent::query()->pluck('content_value','content_key'),'testimonials'=>Testimonial::where('is_published',true)->orderBy('sort_order')->latest()->limit(12)->get()]);}
 public function manage(){return response()->json(['data'=>SiteContent::orderBy('content_key')->get(),'testimonials'=>Testimonial::orderByDesc('created_at')->get()]);}
 public function saveContent(Request $r){$d=$r->validate(['contents'=>['required','array','min:1'],'contents.*.key'=>['required','string','max:100','regex:/^[a-z0-9_]+$/'],'contents.*.label'=>['required','string','max:180'],'contents.*.value'=>['nullable','string','max:12000']]);foreach($d['contents'] as $row)SiteContent::updateOrCreate(['content_key'=>$row['key']],['label'=>$row['label'],'content_value'=>$row['value']??'']);return response()->json(['message'=>'Les textes publics ont été enregistrés.','data'=>SiteContent::orderBy('content_key')->get()]);}
 public function submitPublicTestimonial(Request $r){$d=$r->validate(['person_name'=>['required','string','max:140'],'role_or_location'=>['nullable','string','max:180'],'quote'=>['required','string','min:20','max:3000'],'opportunity_type'=>['nullable','string','max:80'],'rating'=>['required','integer','min:1','max:5']]);$d['is_published']=false;$item=Testimonial::create($d);return response()->json(['message'=>'Merci pour votre témoignage ! Il sera visible après validation par OCD.','data'=>$item],201);}
 public function createTestimonial(Request $r){$d=$r->validate(['person_name'=>['required','string','max:140'],'role_or_location'=>['nullable','string','max:180'],'quote'=>['required','string','max:3000'],'opportunity_type'=>['nullable','string','max:80'],'rating'=>['sometimes','integer','min:1','max:5'],'is_published'=>['sometimes','boolean'],'sort_order'=>['sometimes','integer','min:0','max:10000']]);$item=Testimonial::create($d);return response()->json(['message'=>'Témoignage ajouté.','data'=>$item],201);}
 public function updateTestimonial(Request $r,int $testimonial){$item=Testimonial::findOrFail($testimonial);$d=$r->validate(['person_name'=>['sometimes','required','string','max:140'],'role_or_location'=>['nullable','string','max:180'],'quote'=>['sometimes','required','string','max:3000'],'opportunity_type'=>['nullable','string','max:80'],'rating'=>['sometimes','integer','min:1','max:5'],'is_published'=>['sometimes','boolean'],'sort_order'=>['sometimes','integer','min:0','max:10000']]);$item->update($d);return response()->json(['message'=>'Témoignage mis à jour.','data'=>$item]);}
 public function deleteTestimonial(int $testimonial){Testimonial::findOrFail($testimonial)->delete();return response()->json(['message'=>'Témoignage supprimé.']);}
}
